// Run: node --test src/Game/AI/militaryRating.test.js
//
// "remove region count power entirely, have it be generated by the ai for every
// country by the scenario designer and that then ships with the scenario (like
// how politics generation works except everything is relative to every other
// country it generates and it doesnt waste an entire tool call per country or
// whatever, it does 20 countries per api call)"; "if it is not pregenerated, it
// should just generate it whenever it is needed for the game for a country"
// (the owner, 2026-10-16).

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  MILITARY_BATCH_MOST,
  MILITARY_RATED_FIELDS,
  MILITARY_RELATIVE_LINE,
  describeMilitary,
  militaryRatingRequest,
  militaryTargets,
  rateMilitaryBatch,
  rateMilitaryFigures,
  ratedFigures,
  ratedScaleOf,
  readMilitaryRating,
  readMilitaryRatings,
  wantsRating,
} from "./militaryRating.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const FULL = { quality: 70, technology: 65, land: 75, sea: 40, air: 55, spending: 60, manpowerShare: 10, cavalryShare: 0.2, siegeShare: 0.1 };

test("one request rates up to twenty polities, every one against the others and against those already rated", () => {
  assert.equal(MILITARY_BATCH_MOST, 20);
  const { systemPrompt, userMessage, asked, picking } = militaryRatingRequest({
    polities: [
      { name: "The Dothraki Sea", note: "Horselords of the grass sea; they will not cross the poison water.", population: 1200000 },
      { name: "Braavos" },
      { name: "Volantis", population: 4e6 },
    ],
    rated: [{ name: "The Reach", military: { quality: 55, technology: 50, land: 70, sea: 60, air: 0, spending: 75, manpowerShare: 12 }, population: 9e6 }],
    date: "0298-03-01",
    era: 0,
    rules: "A world of swords and dragons.",
  });
  assert.equal(picking, false);
  assert.deepEqual(asked, ["The Dothraki Sea", "Braavos", "Volantis"]);
  assert.ok(systemPrompt.includes(MILITARY_RELATIVE_LINE));
  assert.match(systemPrompt, /Of two polities, the one whose soldiers fight better has the higher quality/);
  assert.match(systemPrompt, /spending: what its forces have to spend for each soldier, against the other polities'/);
  assert.match(systemPrompt, /0 means it cannot fight there at all: a people that never goes to sea has sea 0/);
  assert.match(systemPrompt, /population: its people, as a plain count, for every polity you rate/);
  assert.match(systemPrompt, /\{"polities":\[\{"polity":"the exact name you were given","population":0,"military":\{"quality":50,"technology":50,"land":50,"sea":50,"air":50,"spending":50,/);
  assert.match(userMessage, /^The scenario's date: 0298-03-01$/m);
  assert.match(userMessage, /^The era its wars are fought in: Before 1500$/m);
  assert.match(userMessage, /ERA & WORLD RULES:\nA world of swords and dragons\./);
  assert.match(userMessage, /ALREADY RATED \(the scale your figures keep to; do not return these\):\n- The Reach: quality 55, technology 50, land 70, sea 60, air 0, spending 75, 12% of its people fit to call up, its people 9000000/);
  assert.match(userMessage, /RATE THESE \(3\):\n- The Dothraki Sea; its people 1200000; what the scenario says of it: Horselords of the grass sea/);
  assert.match(userMessage, /^- Braavos$/m);
  // Twenty to a request.
  const many = militaryRatingRequest({ polities: Array.from({ length: 27 }, (_, at) => ({ name: `Land ${at}` })) });
  assert.equal(many.asked.length, MILITARY_BATCH_MOST);
  // One alone, in the Workshop.
  assert.match(militaryRatingRequest({ polities: [{ name: "Aland" }] }).userMessage, /^RATE THIS ONE:\n- Aland$/m);
  assert.doesNotMatch(militaryRatingRequest({ polities: [{ name: "Aland" }] }).userMessage, /era|RULES|ALREADY/);
});

test("where nobody is rated yet, it is shown the world's polities and rates the strongest of them first", () => {
  const world = Array.from({ length: 45 }, (_, at) => ({ name: `Land ${at}`, note: "a long story", population: at === 3 ? 5e6 : 0 }));
  const { systemPrompt, userMessage, asked, picking, most } = militaryRatingRequest({ pickFrom: world, date: "2024-01-01" });
  assert.equal(picking, true);
  assert.equal(most, 20);
  assert.equal(asked.length, 45, "an answer may name any of them");
  assert.match(userMessage, /THE WORLD'S POLITIES \(45\), nobody rated yet:\n- Land 0\n/);
  assert.match(userMessage, /^- Land 3; its people 5000000$/m);
  assert.match(userMessage, /RATE the 20 of these whose militaries are the strongest, so that every other polity can be rated against them\./);
  assert.match(systemPrompt, /Rate the 20 polities of the list whose militaries are the strongest/);
  assert.doesNotMatch(userMessage, /a long story/, "what is said of each is left out of a list of the whole world");
});

test("the answer is read under the exact names asked, each once, only the figures the AI rates, and its people", () => {
  const read = readMilitaryRatings({
    polities: [
      { polity: "braavos", population: 801234.6, military: { quality: 60, sea: 95, spending: 88, weariness: 40, menPerCounter: 500, bogus: 3 } },
      { polity: "Braavos", military: { quality: 1 } },
      { polity: "Qarth", military: { quality: 50 } },
      { country: "Volantis", military: { land: 70, air: -5 } },
      { polity: "The Dothraki Sea", note: "nothing usable" },
    ],
  }, ["The Dothraki Sea", "Braavos", "Volantis"]);
  assert.deepEqual(read, [
    { name: "Braavos", population: 801235, military: { quality: 60, sea: 95, spending: 88 } },
    { name: "Volantis", military: { land: 70, air: 0 } },
  ]);
  // One asked of, answered without the list.
  assert.deepEqual(readMilitaryRatings({ military: { quality: 75 }, population: 2000 }, ["Aland"]), [{ name: "Aland", population: 2000, military: { quality: 75 } }]);
  assert.deepEqual(readMilitaryRating({ military: { quality: 75, sea: 0, cavalryShare: 0.92, air: -5, weariness: 9 } }), { quality: 75, sea: 0, air: 0, cavalryShare: 0.92 });
  assert.deepEqual(readMilitaryRating({ quality: 40 }), { quality: 40 }, "an answer without its wrapper");
  assert.equal(readMilitaryRating({ military: { note: "no figures" } }), null);
  assert.deepEqual(readMilitaryRatings(null, ["Aland"]), []);
});

test("which figures want rating, how the rated are shown, and who is shown as the scale", () => {
  assert.deepEqual(MILITARY_RATED_FIELDS, ["quality", "technology", "land", "sea", "air", "spending", "manpowerShare", "cavalryShare", "siegeShare"]);
  assert.equal(wantsRating(null), true);
  assert.equal(wantsRating(FULL), false);
  assert.equal(wantsRating({ ...FULL, spending: undefined }), true, "rated before spending was one of the figures");
  assert.deepEqual(ratedFigures({ ...FULL, weariness: 20, muster: [[0.5, 20], [1, 60]] }), FULL);
  assert.equal(describeMilitary({ quality: 60, technology: 75, manpowerShare: 10.25 }, 146e6), "quality 60, technology 75, 10.3% of its people fit to call up, its people 146000000");
  assert.equal(describeMilitary(null), "");
  const scale = ratedScaleOf([
    { name: "Partial", military: { quality: 40 } },
    { name: "Whole", military: FULL, population: 3e6 },
    { name: "Asked", military: FULL },
    { name: "None", military: null },
  ], ["asked"]);
  assert.deepEqual(scale.map((entry) => entry.name), ["Whole", "Partial"], "those rated in full first; never one being rated now");
});

test("a request is asked of the AI once and read; nothing usable is an error", async () => {
  const sent = [];
  const call = async (systemPrompt, messages, options) => {
    sent.push({ systemPrompt, text: messages[0].parts[0].text, options });
    return { rawText: JSON.stringify({ polities: [{ polity: "Aland", population: 5e6, military: { quality: 66 } }, { polity: "Borduria", military: { quality: 44 } }] }) };
  };
  const read = await rateMilitaryBatch({ polities: [{ name: "Aland" }, { name: "Borduria" }] }, { call });
  assert.equal(sent.length, 1, "one request for both");
  assert.equal(sent[0].options.logLabel, "military figures");
  assert.deepEqual(read.map((entry) => entry.name), ["Aland", "Borduria"]);
  await assert.rejects(rateMilitaryBatch({ polities: [{ name: "Cisland" }] }, { call }), /no figures the game could use/);
  // In the Workshop: one country, against the scenario's others (never itself).
  const one = [];
  const figures = await rateMilitaryFigures(
    { name: "Aland", rated: [{ name: "Aland", military: FULL }, { name: "Borduria", military: FULL }] },
    { call: async (systemPrompt, messages) => { one.push(messages[0].parts[0].text); return { rawText: JSON.stringify({ military: { quality: 81 } }) }; } },
  );
  assert.deepEqual(figures, { quality: 81 });
  assert.match(one[0], /ALREADY RATED[^\n]*\n- Borduria: /);
  assert.doesNotMatch(one[0], /- Aland: /);
});

test("the countries at war whose people or figures nobody knows are the ones a war wants rated", () => {
  const world = {
    wars: [
      { id: "w1", status: "active", sideA: ["Aland", "Borduria"], sideB: ["Cisland"] },
      { id: "w2", status: "ended", sideA: ["Esland"], sideB: ["Fenland"] },
    ],
    battlefields: [{ name: "front", status: "active", sides: [["Aland"], ["Dorland"]] }, { name: "old", status: "closed", sides: [["Gaul"], ["Hesse"]] }],
    countryStats: { Borduria: { population: { total: 9e6 }, military: FULL } },
    polityOverrides: { Cisland: { name: "Cisland", population: 3e6 } },
  };
  // Borduria is known whole; Cisland has people but no figures; Aland and Dorland nothing. An ended war, a closed
  // battlefield, wants nobody.
  assert.deepEqual(militaryTargets(world), ["Aland", "Cisland", "Dorland"]);
  assert.deepEqual(militaryTargets(world, { skip: ["aland"] }), ["Cisland", "Dorland"]);
  // A group at war is its scenario designer's to rate, never given a sheet of its own here.
  assert.deepEqual(militaryTargets({ ...world, groups: { Dorland: { name: "Dorland" } } }), ["Aland", "Cisland"]);
});

test("in the Workshop, the AI fills only the fields the designer left empty, rated against the scenario's others", () => {
  const read = (relative) => fs.readFileSync(path.join(here, "../..", relative), "utf8").split("\r\n").join("\n");
  const fields = read("Editor/MilitaryFields.jsx");
  assert.ok(fields.includes("const next = normalizeMilitaryStats({ ...(figures ?? {}), ...(kept ?? {}) });"), "what is set stands");
  assert.ok(fields.includes("{rating ? \"Asking the AI…\" : \"Fill in with AI\"}"));
  assert.ok(fields.includes("figure(\"spending\", \"Spending\""));
  for (const panel of ["Editor/PolitiesPanel.jsx", "Editor/GroupsPanel.jsx", "Editor/SelectionInspector.jsx"]) {
    const source = read(panel);
    assert.ok(source.includes("onRate={() => rateMilitaryFigures({"), panel);
    assert.ok(source.includes("rated: militaryScaleOf("), `${panel}: against the others`);
  }
});
